const pptxgen = require("pptxgenjs");

let pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';

// Define master slide
pres.defineSlideMaster({
  title: 'MASTER_SLIDE',
  background: { color: 'F8FAFC' },
  objects: [
    { rect: { x: 0, y: 0, w: '100%', h: 0.1, fill: { color: '1E293B' } } },
    { rect: { x: 0, y: 0.1, w: '100%', h: 0.05, fill: { color: '0EA5E9' } } },
    { text: { text: "The Power of Vaccination | Our World in Data", options: { x: 0.5, y: 5.25, w: 5, h: 0.3, fontSize: 10, color: '94A3B8' } } }
  ]
});

// Color Palette Variables
const colors = {
  primary: '1E293B', // Slate 800
  secondary: '0F172A', // Slate 900
  accent: '0EA5E9', // Sky 500
  highlight: 'E11D48', // Rose 600
  textLight: 'F8FAFC',
  textDark: '334155',
  cardBg: 'FFFFFF',
  border: 'E2E8F0'
};

// ========================
// Slide 1: Title Slide
// ========================
let s1 = pres.addSlide();
s1.background = { color: colors.secondary };

s1.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: '100%', h: 0.1, fill: { color: colors.accent } });
s1.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 0.5, w: 9.0, h: 4.625, line: { color: colors.textDark, width: 1 } });

s1.addText("The Power of Vaccination", {
  x: 0, y: 1.8, w: '100%', h: 1.2,
  fontSize: 48, bold: true, color: 'FFFFFF', align: 'center',
  fontFace: "Georgia",
  margin: 0
});

s1.addText("From Smallpox Eradication to COVID-19 in Record Time", {
  x: 1, y: 3.0, w: 8, h: 0.6,
  fontSize: 24, color: 'BAE6FD', align: 'center',
  fontFace: "Calibri"
});

s1.addText("A data-driven overview of how vaccines have transformed public health (1796–2020)\nSource: Our World in Data", {
  x: 1, y: 4.2, w: 8, h: 0.8,
  fontSize: 14, color: '94A3B8', align: 'center',
  fontFace: "Calibri"
});


// ========================
// Slide 2: Vaccine Timeline Acceleration
// ========================
let s2 = pres.addSlide({ masterName: "MASTER_SLIDE" });
s2.addText("From 100 Years to Under 1 Year: Vaccine Development Is Accelerating", {
  x: 0.5, y: 0.3, w: 9, h: 0.6,
  fontSize: 22, bold: true, color: colors.primary, fontFace: "Georgia", margin: 0
});

s2.addImage({ path: "/app/benchmark/assets/figure_3.jpg", x: 0.5, y: 1.2, w: 6.0, h: 3.8, sizing: { type: 'contain', w: 6.0, h: 3.8 } });

// Callout Box
s2.addShape(pres.shapes.RECTANGLE, {
  x: 6.8, y: 1.2, w: 2.7, h: 3.8,
  fill: { color: colors.cardBg },
  shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.15 }
});

s2.addText("Pathogen to Licensure", {
  x: 7.0, y: 1.4, w: 2.3, h: 0.4,
  fontSize: 16, bold: true, color: colors.primary, align: 'center', margin: 0
});

s2.addShape(pres.shapes.LINE, { x: 7.0, y: 1.9, w: 2.3, h: 0, line: { color: colors.accent, width: 2 } });

s2.addText([
  { text: "Typhoid Fever\n", options: { fontSize: 16, bold: true, color: colors.textDark } },
  { text: "105 Years", options: { fontSize: 24, bold: true, color: colors.highlight, breakLine: true } },
  { text: " (1884–1989)\n\n", options: { fontSize: 12, color: '64748B' } },

  { text: "Measles\n", options: { fontSize: 16, bold: true, color: colors.textDark } },
  { text: "10 Years", options: { fontSize: 24, bold: true, color: '0EA5E9', breakLine: true } },
  { text: " (1953–1963)\n\n", options: { fontSize: 12, color: '64748B' } },

  { text: "COVID-19\n", options: { fontSize: 16, bold: true, color: colors.textDark } },
  { text: "< 1 Year", options: { fontSize: 28, bold: true, color: '10B981', breakLine: true } },
  { text: " (2020)", options: { fontSize: 12, color: '64748B' } }
], { x: 7.0, y: 2.1, w: 2.3, h: 2.8, align: 'center', margin: 0 });


// ========================
// Slide 3: US Disease Elimination
// ========================
let s3 = pres.addSlide({ masterName: "MASTER_SLIDE" });
s3.addText("100% Case Reduction Achieved for Diphtheria, Polio, and Smallpox in the US", {
  x: 0.5, y: 0.3, w: 9, h: 0.6,
  fontSize: 20, bold: true, color: colors.primary, fontFace: "Georgia", margin: 0
});

// Left Column: Table
s3.addTable([
  [
    { text: "Disease", options: { fill: { color: colors.primary }, color: 'FFFFFF', bold: true } },
    { text: "Pre-Vaccine Cases", options: { fill: { color: colors.primary }, color: 'FFFFFF', bold: true } },
    { text: "Post-Vaccine Cases", options: { fill: { color: colors.primary }, color: 'FFFFFF', bold: true } },
    { text: "Reduction", options: { fill: { color: colors.primary }, color: 'FFFFFF', bold: true } }
  ],
  ["Diphtheria", "158", "0", { text: "100%", options: { bold: true, color: '10B981' } }],
  ["Smallpox", "250", "0", { text: "100%", options: { bold: true, color: '10B981' } }],
  ["Polio (Acute)", "141", "0", { text: "100%", options: { bold: true, color: '10B981' } }],
  ["Measles", "3,044", "0.2", "99.99%"],
  ["Pertussis", "1,534", "52", "96.6%"],
  ["Hepatitis A", "465", "51", "89.0%"],
  ["Hepatitis B", "273", "44", "83.9%"],
  ["Pneumococcal", "233", "139", { text: "40.5%", options: { color: colors.highlight, bold: true } }]
], {
  x: 0.5, y: 1.2, w: 5.5, colW: [1.6, 1.4, 1.4, 1.1],
  border: { pt: 1, color: colors.border },
  rowH: 0.35, fontSize: 12, align: 'center', valAlign: 'middle'
});

